      UPDATE "heroes_watch"."Game" SET "SeriesCode" = COALESCE(existing."SeriesCode", incoming."SeriesCode"),
        "DisplayOrder" = COALESCE(existing."DisplayOrder", incoming."DisplayOrder"),
